local CommonLackMaterialDialog = Class("CommonLackMaterialDialog")

------------ import ------------
local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
------------ import ------------

------------ define ------------
local CommonLackMaterialItemEnvPath = "Game.UI.Common.CommonLackMaterialItem"

------------ define ------------

function CommonLackMaterialDialog:__init()
end

function CommonLackMaterialDialog:__delete()

end

function CommonLackMaterialDialog:Awake()
    SetButtonAction(self.EmptyView.gameObject, function()
        local UIModule            = CS.Engine.UI.UIModule
        UIModule.BackDialog()
    end)
end

function CommonLackMaterialDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local param        = self.controller.Argument.parameters
        local lackGoods = param.lackGoods
        -- print(table.toString(lackGoods))
        self:RefreshUI(lackGoods)

        -- 调整 ui 层级:
        if isNotNull(param.orderInLayer) and type(param.orderInLayer) == "number" then 
            CfUtils.SetAddSortingOrder( self.controller.gameObject, checkInt(param.orderInLayer) )
        end 
    end))
    return coWait
end

function CommonLackMaterialDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

---------------------------------------------------
--- ui logic begin --
---------------------------------------------------

function CommonLackMaterialDialog:RefreshUI(lackGoods)
    local ItemGroup = self.ItemGroup
    local childCount = 1
    for i, v in ipairs(lackGoods) do
        local node
        if i > childCount then
            node = self.Layout.gameObject:AddChild(ItemGroup.gameObject)
        else
            node = ItemGroup
        end
        ---@type CommonLackMaterialItem
        local env = CfUtils.GetLuaScr(node.gameObject, CommonLackMaterialItemEnvPath)
        if not isNull(env) then
            env:RefreshUI(v)
        end
    end
end

